#include <iostream>
#include <memory>

struct S {
    S() { std::cout << "ctor\n"; }
    ~S() { std::cout << "dtor\n"; }
};

int main() {
    auto a = std::make_shared<S>();
    auto b = a;                       // strong 2
    std::cout << a.use_count() << '\n';
    b.reset();                        // strong 1
    std::cout << a.use_count() << '\n';
    a.reset();                        // strong 0 -> dtor
    std::cout << "done\n";
}
// ctor
// 2
// 1
// dtor
// done

#include <iostream>
#include <memory>

int main() {
    std::weak_ptr<int> w;
    {
        auto s = std::make_shared<int>(42);
        w = s;
        std::cout << "strong=" << w.use_count() << '\n';   // 1: w is weak
        if (auto locked = w.lock()) std::cout << "value=" << *locked << '\n';
    }                                       // last strong owner dies here
    std::cout << std::boolalpha << w.expired() << '\n';
    std::cout << (w.lock() ? "locked" : "null") << '\n';
}
// strong=1
// value=42
// true
// null

#include <iostream>
#include <memory>

struct Node {
    std::shared_ptr<Node> next;    // owning forward edge
    std::weak_ptr<Node> prev;      // NON-owning back edge: breaks cycles
    ~Node() { std::cout << "~Node\n"; }
};

int main() {
    auto a = std::make_shared<Node>();
    auto b = std::make_shared<Node>();
    a->next = b;                   // b: strong 2 (main + a->next)
    b->prev = a;                   // a: strong 1 (weak edge adds nothing)
    std::cout << "a=" << a.use_count() << " b=" << b.use_count() << '\n';
}
// a=1 b=2
// ~Node
// ~Node

independentExercise.solution:
(a) After `p->child = c;` the Child's strong count is 2 (stack c + Parent::child). After `c->parent = p;` the Parent's strong count is 2 (stack p + Child::parent). When the stack variables die, each count drops only to 1 - held by the *other* object, which itself cannot die. **Both leak**: no destructor ever prints. This is the classic shared-ownership cycle. (b) ```cpp
#include <iostream>
#include <memory>

struct Child;

struct Parent {
    std::shared_ptr<Child> child;
    ~Parent() { std::cout << "~Parent\n"; }
};
struct Child {
    std::weak_ptr<Parent> parent;          // back edge does not own
    ~Child() { std::cout << "~Child\n"; }
    void report() {
        if (auto p = parent.lock())        // safe: ownership only while alive
            std::cout << "my parent is alive\n";
        else
            std::cout << "parent gone\n";
    }
};

int main() {
    auto p = std::make_shared<Parent>();
    auto c = std::make_shared<Child>();
    p->child = c;
    c->parent = p;
    std::cout << "p=" << p.use_count() << " c=" << c.use_count() << '\n';
    c->report();
}
```
Output: `p=1 c=2`, `my parent is alive`, then `~Child` and `~Parent` - proof the cycle is broken. (c) Parent's strong count is 1 (only the stack pointer; the weak edge adds nothing strong), Child's is 2 (stack + parent's owning edge). Destructors run at scope exit because no count is pinned above zero.

