#include <iostream>
#include <memory>
int main() {
    std::weak_ptr<int> w;
    {
        auto s = std::make_shared<int>(42);
        w = s;
        std::cout << w.use_count() << "\n";
        if (auto p = w.lock()) std::cout << *p << "\n";
    }
    std::cout << (w.expired() ? "expired" : "alive") << "\n";
